import {AXES} from './context.js';
import {describeAxisPosition,renderAxisSummary} from './axis-presentation.js';
import {COUNTRY_AXES,rankCountries,countryCatalog} from './countries.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const IDEOLOGY_COPY={
 socialdemocrata:{name:'Socialdemocracia',phrase:'Prefiero una economía con iniciativa privada, un Estado activo y derechos sociales que reduzcan las desigualdades.'},
 liberal:{name:'Liberalismo de mercado',phrase:'Prefiero más libertad para emprender, competir y elegir, con impuestos contenidos y apertura a los cambios sociales.'},
 conservadora:{name:'Conservadurismo de mercado',phrase:'Prefiero una economía con iniciativa privada y cambios prudentes que preserven las tradiciones sociales.'},
 socialconservadora:{name:'Conservadurismo social',phrase:'Prefiero protección social y un Estado presente en la economía, junto con valores familiares y sociales tradicionales.'},
 mixta:{name:'Pragmatismo',phrase:'Prefiero combinar mercado, regulación y políticas sociales según cada problema, sin una inclinación marcada hacia uno de esos polos.'}
};
export function ideologyDescription(model){return {...model,...IDEOLOGY_COPY[model.id]}}
export function percentageBadge(score,label='afinidad'){return `<div class="percentage-badge"><strong>${score}%</strong><span>${esc(label)}</span></div>`}
export function differenceCard(x,{heading=true}={}){const a=AXES[x.axis],u=describeAxisPosition(a,x.user),r=describeAxisPosition(a,x.reference);return `<article class="difference difference-card">${heading?`<h4>${esc(a.name)}</h4>`:''}<div class="comparison-readings"><span>Vos <strong>${esc(u.label)}</strong></span><span>Referencia <strong>${esc(r.label)}</strong></span></div><div class="dual-track" role="img" aria-label="${esc(a.name)}: vos ${x.user}, referencia ${x.reference}; 0 ${esc(a.left)}, 100 ${esc(a.right)}"><i style="left:${x.user}%" aria-hidden="true"></i><b style="left:${x.reference}%" aria-hidden="true"></b></div><div class="pole-labels"><span>${esc(a.left)}</span><span>${esc(a.right)}</span></div></article>`}
export function renderDifferences(entity,details){return `<p>Comparación con <strong>${esc(entity.name)}</strong>. Punto de color: vos. Círculo vacío: referencia.</p><h3>En qué coincidís más</h3><div class="difference-grid">${details.near.map(differenceCard).join('')}</div><h3>En qué te diferenciás más</h3><div class="difference-grid">${details.far.length?details.far.map(differenceCard).join(''):'<p>Los puntajes coinciden en los cuatro ejes comparados.</p>'}</div><a href="#comparar/${entity.id}">Ver los doce ejes y sus fuentes</a>`}
export function distinctivePriorities(profile,entities){
 const items=AXES.map((axis,i)=>{const known=entities.map(e=>e.profile[i]).filter(Number.isFinite).sort((a,b)=>a-b);if(!known.length)return null;const middle=Math.floor(known.length/2),median=known.length%2?known[middle]:(known[middle-1]+known[middle])/2;return {axis:i,user:profile[i],reference:median,gap:Math.abs(profile[i]-median)}}).filter(Boolean);
 const unusual=[...items].sort((a,b)=>b.gap-a.gap||a.axis-b.axis)[0],typical=[...items].sort((a,b)=>a.gap-b.gap||a.axis-b.axis)[0];
 return `<div class="distinctive-grid">${[[unusual,'Tu posición más distinta'],[typical,'Tu punto más cercano']].map(([x,label])=>`<article><p class="small">${label}</p>${renderAxisSummary(AXES[x.axis],x.user)}<p class="small">${x.gap===0?'Coincidís con la mediana.':`A ${x.gap} puntos de la mediana de las referencias.`}</p>${differenceCard(x,{heading:false})}</article>`).join('')}</div><details><summary>Cómo se compara</summary><p>Se compara tu posición con la mediana de las ${entities.length} referencias documentadas en cada eje con datos. «Distinta» describe una distancia dentro de este catálogo; no significa rara entre la población. Los ejes sin evidencia quedan fuera.</p></details>`;
}
export function renderCountryResults(profile,mode='current'){
 const ranked=rankCountries(profile,mode),lead=ranked[0],catalog=countryCatalog(mode);
 const card=x=>`<article class="country-match">${mode==='current'?`<img class="country-flag-image" src="flags/${x.entity.id}.svg" alt="Bandera de ${esc(x.entity.name)}" width="110" height="75">`:`<span class="country-era" aria-hidden="true">${esc(x.entity.period.match(/\d{4}/)?.[0]||'')}</span>`}<div><h3>${esc(x.entity.name)}</h3><p>${esc(x.entity.period)}</p></div>${percentageBadge(x.score)}<details><summary>Más sobre ${esc(x.entity.name)}</summary><p>${x.entity.notes.map(esc).join(' ')}</p><p>Escala editorial: ${COUNTRY_AXES.map(i=>`${esc(AXES[i].name)} ${x.entity.profile[i]}`).join(' · ')}.</p>${x.entity.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join(' · ')}</details></article>`;
 return `<p class="small country-coverage">${ranked.length} perfiles comparables de ${catalog.length} entradas. Afinidad constitucional orientativa sobre Economía, Instituciones y Religión; no mide a los habitantes ni las políticas actuales del gobierno.</p>${card(lead)}<h3>También cerca de vos</h3><div class="country-nearby">${ranked.slice(1).map(card).join('')}</div><details><summary>Ver catálogo completo y cobertura</summary><label>Buscar país<input id="country-search" type="search" placeholder="Nombre del país" autocomplete="off"></label><ul class="country-catalog">${catalog.map(c=>{const match=ranked.find(x=>x.entity.id===c.id);return `<li data-country-search="${esc(c.name.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,''))}"><span>${c.flag||''} ${esc(c.name)}${c.period?' · '+esc(c.period):''}</span><strong>${match?match.score+'%':'Sin datos suficientes'}</strong></li>`}).join('')}</ul><p id="country-empty" hidden>No hay países con ese nombre en este catálogo.</p></details><details><summary>Fuentes y criterio de afinidad</summary><p>Comparación inicial del texto constitucional, no clasificación completa del país. Economía: 25 para provisión pública o nacionalización explícita, 50 para propiedad con límites sociales y 75 para protección fuerte de la propiedad. Instituciones: 25 para contrapesos, 50 para un Ejecutivo más fuerte y 100 para un soberano sin responsabilidad parlamentaria. Religión: 0 para separación o no establecimiento, 75 para tradición religiosa ligada al soberano y 100 para religión oficial. Son interpretaciones editoriales, no datos publicados por esas fuentes.</p><p>Afinidad = 100 menos la distancia absoluta media en esos tres ejes. Los demás ejes permanecen sin puntaje. La misma rúbrica se aplica a todos los perfiles. Los textos históricos no equivalen a su aplicación real y no representan los derechos de todas las personas de su época.</p><p>Catálogo actual: 193 miembros y dos observadores de la ONU. Nombres: <a href="https://github.com/mledoze/countries" target="_blank" rel="noopener noreferrer">mledoze/countries · ODbL</a>. No cubre todos los Estados con reconocimiento disputado. El catálogo histórico es una selección abierta, sin pretensión de cubrir toda la historia.</p></details>`;
}
